[WebMethod]
public string CheckUnitNoOutstanding(int siteID, string unitCode, string unitNo)
{
try
{
log.InfoFormat("CheckUnitNoOutstanding() - Start");
log.DebugFormat("Parameters - SiteID: {0}, UnitCode: {1}, UnitNo: {2}", siteID, unitCode, unitNo);

Objects.ResponseGeneralLanguage<bool> resp = new Objects.ResponseGeneralLanguage<bool>();
DataTable dt = ClsBCD.GetOutStanding(siteID, unitCode, unitNo);

if (dt != null && dt.Rows.Count > 0)
{
int flag = Convert.ToInt32(dt.Rows[0]["Result"]);
resp.code = 1;
resp.data = (flag == 1);
resp.message.id = resp.data ? "Tidak memiliki outstanding" : "Memiliki outstanding";
resp.message.en = resp.data ? "No outstanding" : "Has outstanding";
}
else
{
resp.code = 0;
resp.data = false;
resp.message.id = "Data tidak ditemukan";
resp.message.en = "Data not found";
}

log.DebugFormat("CheckUnitNoOutstanding() - resp.code={0}, resp.message.en={1}, resp.data={2}", resp.code, resp.message.en, resp.data);
log.InfoFormat("CheckUnitNoOutstanding() - End");
return JsonConvert.SerializeObject(resp);
}
catch (Exception ex)
{
Objects.ResponseGeneralLanguage<bool> resp = new Objects.ResponseGeneralLanguage<bool>();
resp.code = -1;
resp.data = false;
resp.message.en = ex.Message;
log.DebugFormat("CheckUnitNoOutstanding() - resp.code={0}, resp.message.en={1}", resp.code, resp.message.en);
log.ErrorFormat("CheckUnitNoOutstanding() - Error={0}", ex.Message);
return JsonConvert.SerializeObject(resp);
}
}

